<script>
(() => {
'use strict';
const TAU = Math.PI * 2;
const clamp  = (v,a,b) => v < a ? a : v > b ? b : v;
const smooth = (a,b,x) => { const t = clamp((x-a)/(b-a),0,1); return t*t*(3-2*t); };

const stage    = document.getElementById('stage');
const ctx      = stage.getContext('2d');
const cursorEl = document.getElementById('cursor');
const rvRot    = document.getElementById('rv-rot');
const rvMelt   = document.getElementById('rv-melt');
const rvZoom   = document.getElementById('rv-zoom');
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

let W = 0, H = 0, dpr = 1;
const resize = () => {
  dpr = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth; H = window.innerHeight;
  stage.width = Math.round(W*dpr); stage.height = Math.round(H*dpr);
  ctx.setTransform(dpr,0,0,dpr,0,0);
};
addEventListener('resize', resize);
resize();

/* film-grain tile, generated once */
const grain = document.createElement('canvas');
grain.width = grain.height = 144;
{
  const g = grain.getContext('2d');
  const im = g.createImageData(144,144), d = im.data;
  for (let i = 0; i < d.length; i += 4){
    const v = (Math.random()*255)|0;
    d[i] = d[i+1] = d[i+2] = v; d[i+3] = 12;
  }
  g.putImageData(im,0,0);
}
const grainPat = ctx.createPattern(grain,'repeat');

/* ——— state ——— */
const S = {
  rot: -0.9, spinVel: 0,
  baseSpeed: reduceMotion ? 0 : 0.21,     // rad/s, stately drift
  zoom: 1, zoomT: 1,
  M: reduceMotion ? 0 : 1.0, Mv: 0,       // melt spring — starts denatured, zips shut on load
  px: W*0.5, py: H*0.52, pyS: H*0.52,     // pointer + smoothed follow position
  hover: false, dragging: false, lastX: 0, moveDx: 0,
};

/* ——— input ——— */
const pointers = new Map();
let pinchD = 0;

stage.addEventListener('pointerdown', e => {
  stage.setPointerCapture(e.pointerId);
  pointers.set(e.pointerId, {x:e.clientX, y:e.clientY});
  if (e.pointerType === 'touch') cursorEl.style.opacity = '0';
  if (pointers.size === 1){
    S.dragging = true; S.lastX = e.clientX; S.moveDx = 0;
  } else if (pointers.size === 2){
    const [a,b] = [...pointers.values()];
    pinchD = Math.hypot(a.x-b.x, a.y-b.y);
  }
});

addEventListener('pointermove', e => {
  if (e.pointerType !== 'touch'){
    S.px = e.clientX; S.py = e.clientY; S.hover = true;
    cursorEl.style.opacity = '1';
    cursorEl.style.setProperty('--x', e.clientX + 'px');
    cursorEl.style.setProperty('--y', e.clientY + 'px');
  }
  const p = pointers.get(e.pointerId);
  if (p){ p.x = e.clientX; p.y = e.clientY; }
  if (pointers.size === 2){
    const [a,b] = [...pointers.values()];
    const d = Math.hypot(a.x-b.x, a.y-b.y);
    if (pinchD > 0) S.zoomT = clamp(S.zoomT * d/pinchD, 0.62, 1.5);
    pinchD = d;
    return;
  }
  if (S.dragging && pointers.size === 1){
    S.moveDx += e.clientX - S.lastX;
    S.lastX = e.clientX;
  }
});

const release = e => {
  pointers.delete(e.pointerId);
  if (pointers.size < 2) pinchD = 0;
  if (pointers.size === 0){
    S.dragging = false;                      // spinVel persists → fling with friction
  } else if (pointers.size === 1){           // pinch → back to single-finger drag
    const [a] = [...pointers.values()];
    S.dragging = true; S.lastX = a.x; S.moveDx = 0;
  }
};
addEventListener('pointerup', release);
addEventListener('pointercancel', release);
addEventListener('blur', () => { S.hover = false; S.dragging = false; pointers.clear(); pinchD = 0; });
document.documentElement.addEventListener('mouseleave', () => { S.hover = false; });

addEventListener('wheel', e => {
  e.preventDefault();
  S.zoomT = clamp(S.zoomT * Math.exp(-e.deltaY * 0.0012), 0.62, 1.5);
}, {passive:false});

addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft')       S.spinVel = clamp(S.spinVel - 1.3, -5, 5);
  else if (e.key === 'ArrowRight') S.spinVel = clamp(S.spinVel + 1.3, -5, 5);
});

/* ——— color: sea-glass teal (strand A) vs. warm sand (strand B) ——— */
function strandCss(side, f, m, a, dl){
  const hue = side === 0 ? 168 : 35;
  const sat = (side === 0 ? 46 : 44) * (0.72 + 0.28*f);          // desaturate with depth
  const L   = Math.min((side === 0 ? 30 : 27) + 46*f + 5*Math.max(m,0) + (dl || 0), 88);
  return 'hsla(' + hue + ',' + sat.toFixed(1) + '%,' + L.toFixed(1) + '%,' + clamp(a,0,1).toFixed(3) + ')';
}

/* ——— geometry of the plate ——— */
function geometry(){
  const cx = W*0.5, cy = H*0.52;
  const R0     = clamp(Math.min(W*0.30, H*0.34), 78, 252) * S.zoom;
  const helixH = Math.min(H*0.68, 780) * S.zoom;
  const bpPx   = 16 * S.zoom;                                    // axial spacing per base pair
  const bpCount= Math.max(2, Math.floor(helixH/bpPx) - 1);
  const off    = (helixH - bpCount*bpPx) * 0.5;
  const twist  = TAU / (10.5 * bpPx);                            // canonical B-DNA: 10.5 bp / turn
  return { cx, cy, R0, helixH, bpPx, bpCount, off, twist,
           yTop: cy - helixH/2, yBot: cy + helixH/2,
           sigma: Math.max(52, helixH*0.115) };
}

/* ——— annotations: bp ruler (right) + one-turn bracket (left), beneath the figure ——— */
function drawAnnotations(g, rev){
  if (rev < 0.03) return;
  const want = Math.min(g.R0*1.78 + 26, W*0.5 - 46);
  if (want <= g.R0*1.62 + 10) return;                            // no clean room beside the molecule
  ctx.font = '9px ui-monospace, Menlo, Consolas, "Liberation Mono", monospace';
  ctx.textBaseline = 'middle'; ctx.lineWidth = 1;
  const yEnd = g.yTop + g.off + g.bpCount*g.bpPx + 14;

  const rx = g.cx + want;
  if (rx + 44 < W){
    ctx.strokeStyle = 'rgba(198,208,216,' + (0.10*rev).toFixed(3) + ')';
    ctx.beginPath(); ctx.moveTo(rx, g.yTop - 14); ctx.lineTo(rx, yEnd); ctx.stroke();
    ctx.fillStyle = 'rgba(166,177,186,' + (0.55*rev).toFixed(3) + ')';
    ctx.textAlign = 'left';
    ctx.fillText('bp', rx + 13, g.yTop - 14);
    for (let j = 0; j <= g.bpCount; j++){
      const maj = j % 10 === 0, has = j % 5 === 0;
      if (!maj && !has) continue;
      const y = g.yTop + g.off + j*g.bpPx;
      ctx.strokeStyle = 'rgba(198,208,216,' + ((maj ? 0.30 : 0.14)*rev).toFixed(3) + ')';
      ctx.beginPath(); ctx.moveTo(rx, y); ctx.lineTo(rx + (maj ? 9 : 5), y); ctx.stroke();
      if (maj) ctx.fillText(String(j), rx + 14, y);
    }
  }

  const lx = g.cx - want;
  if (lx - 64 > 0){
    const th = 10.5 * g.bpPx, by0 = g.cy - th/2, by1 = g.cy + th/2;
    ctx.strokeStyle = 'rgba(198,208,216,' + (0.16*rev).toFixed(3) + ')';
    ctx.beginPath();
    ctx.moveTo(lx, by0); ctx.lineTo(lx, by1);
    ctx.moveTo(lx, by0); ctx.lineTo(lx - 7, by0);
    ctx.moveTo(lx, by1); ctx.lineTo(lx - 7, by1);
    ctx.stroke();
    ctx.save();
    ctx.translate(lx - 14, g.cy); ctx.rotate(-Math.PI/2);
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(166,177,186,' + (0.50*rev).toFixed(3) + ')';
    ctx.fillText('one turn · 10.5 base pairs', 0, 0);
    ctx.restore();
  }
}

/* ——— main loop ——— */
let last = performance.now(); const t0 = last;
let curState = '__', meltTint = -1;

function frame(now){
  const dt = clamp((now - last)/1000, 0.0001, 0.05); last = now;
  const t  = (now - t0)/1000;

  S.zoom += (S.zoomT - S.zoom) * (1 - Math.exp(-dt*9));
  const g = geometry();

  /* spin: drag sets velocity, friction hands it back to the base drift */
  if (S.dragging){
    if (S.moveDx !== 0){
      const dr = -S.moveDx * 0.0045;           // front of the helix follows the pointer
      S.rot += dr;
      S.spinVel = S.spinVel*0.72 + (dr/dt)*0.28;
      S.moveDx = 0;
    } else S.spinVel *= Math.exp(-dt*10);      // held still → settle quickly
  } else {
    S.rot += (S.baseSpeed + S.spinVel) * dt;
    S.spinVel *= Math.exp(-dt*1.9);
  }
  S.spinVel = clamp(S.spinVel, -5, 5);

  /* denaturation spring — slightly underdamped, so the re-zip overshoots a hair */
  const prox = Math.max(0, 1 - Math.abs(S.px - g.cx)/(g.R0*1.9));
  const vert = Math.exp(-((S.py - g.cy)*(S.py - g.cy)) / (2*Math.pow(g.helixH*0.62, 2)));
  const mT   = (S.hover && !S.dragging && prox > 0.02) ? Math.min(1, prox*prox*1.25)*vert : 0;
  S.Mv += (mT - S.M) * 46 * dt;
  S.Mv *= Math.exp(-dt*8.4);
  S.M  = clamp(S.M + S.Mv*dt, -0.12, 1.05);
  S.pyS += (S.py - S.pyS) * (1 - Math.exp(-dt*11));

  const cs = S.dragging ? 'g' : (S.M > 0.06 ? 'm' : '');
  if (cs !== curState){
    cursorEl.classList.toggle('is-grab', cs === 'g');
    cursorEl.classList.toggle('is-melt', cs === 'm');
    curState = cs;
  }

  render(now, t, g);
  readout();
  requestAnimationFrame(frame);
}

function render(now, t, g){
  /* backdrop + studio lift */
  ctx.fillStyle = '#0b0e11'; ctx.fillRect(0,0,W,H);
  const lift = ctx.createRadialGradient(g.cx, g.cy - g.helixH*0.06, 0, g.cx, g.cy, Math.max(W,H)*0.62);
  lift.addColorStop(0,   'rgba(152,170,180,0.055)');
  lift.addColorStop(0.55,'rgba(152,170,180,0.014)');
  lift.addColorStop(1,   'rgba(152,170,180,0)');
  ctx.fillStyle = lift; ctx.fillRect(0,0,W,H);

  const rev = reduceMotion ? 1 : smooth(0, 1, Math.min(1, (now - t0)/750));

  drawAnnotations(g, rev);

  /* fine sampling along both backbones */
  const step = 4;
  const n = Math.max(8, Math.round(g.helixH/step));
  const breath = reduceMotion ? 1 : 1 + 0.013*Math.sin(t*0.55);   // barely-perceptible breathing
  const inv2s2 = 1 / (2*g.sigma*g.sigma);

  const ys = new Float32Array(n+1), ax = new Float32Array(n+1), bx = new Float32Array(n+1),
        az = new Float32Array(n+1), bz = new Float32Array(n+1),
        fA = new Float32Array(n+1), fB = new Float32Array(n+1), mm = new Float32Array(n+1);
  for (let i = 0; i <= n; i++){
    const y = Math.min(g.yTop + i*step, g.yBot);
    const m = S.M * Math.exp(-(y - S.pyS)*(y - S.pyS) * inv2s2);
    const th = (S.rot + (y - g.cy)*g.twist) * (1 - m);            // melt relaxes the local twist
    const s = Math.sin(th), c = Math.cos(th);
    const r = g.R0 * breath * (1 + 0.55*m);                       // …and pushes the strands apart
    ys[i] = y; mm[i] = m;
    az[i] =  r*s;  bz[i] = -r*s;                                  // strand B lives at θ + π
    ax[i] = g.cx + r*c*(1 + s*0.09);                              // mild x-only perspective,
    bx[i] = g.cx - r*c*(1 - s*0.09);                              // y stays exact → rungs horizontal
    fA[i] = (s + 1)*0.5; fB[i] = (1 - s)*0.5;
  }

  /* base-pair sampling: rungs + beads */
  const bp = g.bpCount;
  const ny = new Float32Array(bp+1), nAx = new Float32Array(bp+1), nBx = new Float32Array(bp+1),
        nAz = new Float32Array(bp+1), nBz = new Float32Array(bp+1),
        nFA = new Float32Array(bp+1), nFB = new Float32Array(bp+1), nM = new Float32Array(bp+1);
  for (let j = 0; j <= bp; j++){
    const y = Math.min(g.yTop + g.off + j*g.bpPx, g.yBot);
    const m = S.M * Math.exp(-(y - S.pyS)*(y - S.pyS) * inv2s2);
    const th = (S.rot + (y - g.cy)*g.twist) * (1 - m);
    const s = Math.sin(th), c = Math.cos(th);
    const r = g.R0 * breath * (1 + 0.55*m);
    ny[j] = y; nM[j] = m;
    nAz[j] =  r*s;  nBz[j] = -r*s;
    nAx[j] = g.cx + r*c*(1 + s*0.09);
    nBx[j] = g.cx - r*c*(1 - s*0.09);
    nFA[j] = (s + 1)*0.5; nFB[j] = (1 - s)*0.5;
  }

  /* painter's list, far → near — this is what weaves the strands over/under each other */
  const items = [];
  for (let i = 0; i < n; i++){
    items.push({z:(az[i]+az[i+1])*0.5, k:0, x1:ax[i], y1:ys[i], x2:ax[i+1], y2:ys[i+1], f:(fA[i]+fA[i+1])*0.5, m:mm[i]});
    items.push({z:(bz[i]+bz[i+1])*0.5, k:1, x1:bx[i], y1:ys[i], x2:bx[i+1], y2:ys[i+1], f:(fB[i]+fB[i+1])*0.5, m:mm[i]});
  }
  for (let j = 0; j <= bp; j++){
    items.push({z:0,      k:2, j});          // rung passes through the axis → depth key 0
    items.push({z:nAz[j], k:3, j, side:0});
    items.push({z:nBz[j], k:3, j, side:1});
  }
  items.sort((p,q) => p.z - q.z);

  ctx.lineCap = 'round';
  const halo = dpr < 1.5;                    // soft under-stroke tames hairline shimmer on 1× displays
  for (let idx = 0; idx < items.length; idx++){
    const it = items[idx];
    if (it.k < 2){                           /* backbone segment */
      const side = it.k, f = it.f, m = it.m;
      const w = 0.9 + 1.5*f;
      const a = (0.30 + 0.66*f) * rev;
      if (halo){
        ctx.strokeStyle = strandCss(side, f, m, a*0.20, 0);
        ctx.lineWidth = w + 1.7;
        ctx.beginPath(); ctx.moveTo(it.x1, it.y1); ctx.lineTo(it.x2, it.y2); ctx.stroke();
      }
      ctx.strokeStyle = strandCss(side, f, m, a, 0);
      ctx.lineWidth = w;
      ctx.beginPath(); ctx.moveTo(it.x1, it.y1); ctx.lineTo(it.x2, it.y2); ctx.stroke();
    } else if (it.k === 2){                  /* base-pair rung */
      const j = it.j, m = nM[j], f1 = nFA[j], f2 = nFB[j], y = ny[j];
      const fade = (1 - smooth(0.10, 0.78, m)) * rev;   // H-bonds dissolve as the pair melts
      if (fade <= 0.02) continue;
      const at   = (j & 1) === 0;
      const bond = at ? 0.78 : 1.0;            // A–T · two H-bonds / G–C · three
      const bw   = at ? 0.85 : 1.12;
      const a1 = Math.min((0.15 + 0.46*f1) * bond * fade, 1);
      const a2 = Math.min((0.15 + 0.46*f2) * bond * fade, 1);
      const gr = ctx.createLinearGradient(nAx[j], y, nBx[j], y);  // rung spans teal → sand
      gr.addColorStop(0, strandCss(0, f1, m, a1, 0));
      gr.addColorStop(1, strandCss(1, f2, m, a2, 0));
      ctx.strokeStyle = gr;
      ctx.lineWidth = Math.max(0.55, (0.65 + (f1 + f2)*0.5) * bw * (1 + 0.5*Math.max(m, 0)));
      ctx.beginPath(); ctx.moveTo(nAx[j], y); ctx.lineTo(nBx[j], y); ctx.stroke();
    } else {                                 /* backbone bead */
      const j = it.j, side = it.side;
      const f = side === 0 ? nFA[j] : nFB[j], m = nM[j];
      const r = (1.35 + 2.25*f) * (1 + 0.4*m);
      const a = Math.min((0.26 + 0.72*f) * rev, 1);
      ctx.fillStyle = strandCss(side, f, m, a, 5);
      ctx.beginPath();
      ctx.arc(side === 0 ? nAx[j] : nBx[j], ny[j], r, 0, TAU);
      ctx.fill();
    }
  }

  /* plate falloff + film grain */
  const vig = ctx.createRadialGradient(g.cx, g.cy, Math.min(W,H)*0.36, g.cx, g.cy, Math.max(W,H)*0.78);
  vig.addColorStop(0, 'rgba(4,6,9,0)');
  vig.addColorStop(1, 'rgba(4,6,9,0.48)');
  ctx.fillStyle = vig; ctx.fillRect(0,0,W,H);

  ctx.save();
  if (!reduceMotion) ctx.translate(-((now*0.021)%144), -((now*0.0137)%144));
  ctx.fillStyle = grainPat;
  ctx.fillRect(0, 0, W + 144, H + 144);
  ctx.restore();
}

function readout(){
  const deg = (((S.rot % TAU) + TAU) % TAU) * 180/Math.PI;
  rvRot.textContent  = deg.toFixed(1).padStart(5,'0') + '°';
  const mp = clamp(S.M, 0, 1);
  rvMelt.textContent = String(Math.round(mp*100)).padStart(2,'0') + '%';
  rvZoom.textContent = '×' + S.zoom.toFixed(2);
  const tint = mp > 0.04 ? 1 : 0;
  if (tint !== meltTint){ meltTint = tint; rvMelt.style.color = tint ? '#d9a45e' : ''; }
}

requestAnimationFrame(frame);
